CREATE TABLE IF NOT EXISTS guild_operator_cohort_mutations (
    InstallationGeneration TEXT NOT NULL CHECK(InstallationGeneration=upper(InstallationGeneration) AND length(InstallationGeneration)=36 AND substr(InstallationGeneration,9,1)='-' AND substr(InstallationGeneration,14,1)='-' AND substr(InstallationGeneration,19,1)='-' AND substr(InstallationGeneration,24,1)='-' AND length(replace(InstallationGeneration,'-',''))=32 AND replace(InstallationGeneration,'-','') NOT GLOB '*[^0-9A-F]*' AND InstallationGeneration<>'00000000-0000-0000-0000-000000000000'),
    PrincipalId TEXT NOT NULL CHECK(PrincipalId=upper(PrincipalId) AND length(PrincipalId)=36 AND substr(PrincipalId,9,1)='-' AND substr(PrincipalId,14,1)='-' AND substr(PrincipalId,19,1)='-' AND substr(PrincipalId,24,1)='-' AND length(replace(PrincipalId,'-',''))=32 AND replace(PrincipalId,'-','') NOT GLOB '*[^0-9A-F]*' AND PrincipalId<>'00000000-0000-0000-0000-000000000000'),
    ParentId TEXT NOT NULL CHECK(ParentId=upper(ParentId) AND length(ParentId)=36 AND substr(ParentId,9,1)='-' AND substr(ParentId,14,1)='-' AND substr(ParentId,19,1)='-' AND substr(ParentId,24,1)='-' AND length(replace(ParentId,'-',''))=32 AND replace(ParentId,'-','') NOT GLOB '*[^0-9A-F]*' AND ParentId<>'00000000-0000-0000-0000-000000000000'),
    IdempotencyKey TEXT NOT NULL CHECK(IdempotencyKey=upper(IdempotencyKey) AND length(IdempotencyKey)=36 AND substr(IdempotencyKey,9,1)='-' AND substr(IdempotencyKey,14,1)='-' AND substr(IdempotencyKey,19,1)='-' AND substr(IdempotencyKey,24,1)='-' AND length(replace(IdempotencyKey,'-',''))=32 AND replace(IdempotencyKey,'-','') NOT GLOB '*[^0-9A-F]*' AND IdempotencyKey<>'00000000-0000-0000-0000-000000000000'),
    ReceiptId TEXT NOT NULL CHECK(ReceiptId=upper(ReceiptId) AND length(ReceiptId)=36 AND substr(ReceiptId,9,1)='-' AND substr(ReceiptId,14,1)='-' AND substr(ReceiptId,19,1)='-' AND substr(ReceiptId,24,1)='-' AND length(replace(ReceiptId,'-',''))=32 AND replace(ReceiptId,'-','') NOT GLOB '*[^0-9A-F]*' AND ReceiptId<>'00000000-0000-0000-0000-000000000000'),
    ActionCode INTEGER NOT NULL CHECK(typeof(ActionCode)='integer' AND ActionCode IN(1,2,3,4,5)),
    AcceptedAtUtc TEXT NOT NULL,
    RequestDigest BLOB NOT NULL CHECK(typeof(RequestDigest)='blob' AND length(RequestDigest)=32),
    CohortId TEXT NOT NULL REFERENCES guild_cohorts(Id) ON DELETE RESTRICT CHECK(CohortId=upper(CohortId) AND length(CohortId)=36 AND substr(CohortId,9,1)='-' AND substr(CohortId,14,1)='-' AND substr(CohortId,19,1)='-' AND substr(CohortId,24,1)='-' AND length(replace(CohortId,'-',''))=32 AND replace(CohortId,'-','') NOT GLOB '*[^0-9A-F]*' AND CohortId<>'00000000-0000-0000-0000-000000000000'),
    ResultObjectId TEXT NULL CHECK(ResultObjectId IS NULL OR (ResultObjectId=upper(ResultObjectId) AND length(ResultObjectId)=36 AND substr(ResultObjectId,9,1)='-' AND substr(ResultObjectId,14,1)='-' AND substr(ResultObjectId,19,1)='-' AND substr(ResultObjectId,24,1)='-' AND length(replace(ResultObjectId,'-',''))=32 AND replace(ResultObjectId,'-','') NOT GLOB '*[^0-9A-F]*' AND ResultObjectId<>'00000000-0000-0000-0000-000000000000')),
    AcceptedRevision INTEGER NOT NULL CHECK(typeof(AcceptedRevision)='integer' AND AcceptedRevision>=1),
    PRIMARY KEY(InstallationGeneration,PrincipalId,ActionCode,ParentId,IdempotencyKey),
    UNIQUE(ReceiptId),
    CHECK((ActionCode IN(3,4) AND ResultObjectId IS NOT NULL) OR (ActionCode IN(1,2,5) AND ResultObjectId IS NULL))
);
